fn sqlite_snapshot_semio_video_rejects_owner_ordinal_scalar_and_budget_corruption(){let original=project(&fixture());for change in 0..6{let mut db=original.clone();match change{0=>db.table_mut("semio_video_sample").unwrap().rows[0].values[1]=SqliteValue::Integer(999),1=>db.table_mut("semio_video_sample").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>db.table_mut("semio_video_sample").unwrap().rows[0].values[3]=SqliteValue::Text("18446744073709551616".into()),3=>db.table_mut("semio_video_sample").unwrap().rows[0].values[4]=SqliteValue::Integer(2),4=>db.table_mut("semio_video_stream").unwrap().rows[0].values[8]=SqliteValue::Text("0".into()),_=>db.table_mut("semio_video_sample").unwrap().rows[0].values[3]=SqliteValue::Text("00".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioVideoSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
