/// 🧮️ Projects owned semantic rows under the caller's typed resource control.
pub fn project_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{
control.check_rows(self.nodes.len().checked_add(self.edges.len()).and_then(|count|count.checked_add(1)).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Semio flow row count overflow"))?)?;let mut nodes=BTreeMap::new();for(ordinal,node)in self.nodes.iter().enumerate(){if ordinal%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;}if nodes.insert(node.id.as_str(),number(ordinal+1)?).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio flow node identifier"));}}
